parameters.jsCode:
// ============================================
// NODO: ValidateWorkoutDuration
// PROPÓSITO: Validar que rutinas diarias caben en tiempo disponible
// VERSIÓN: 2.0 - Priorización muscular + eliminación de ejercicios
// ============================================

const userProfile = $('ProcessUserPreferences').first().json;

// Get all workout items from input
const allWorkouts = $input.all().map(item => item.json);

// Get priority muscles from user profile
const priorityMuscles = userProfile.processed?.priority_muscles_en || [];

// Build exercise lookup from GetExercisesByPattern (for main_muscle, secondary_muscles)
const exerciseLookup = {};
try {
  $('GetExercisesByPattern').all().forEach(item => {
    const ex = item.json;
    exerciseLookup[ex.exercise_id] = {
      main_muscle: ex.main_muscle,
      secondary_muscles: ex.secondary_muscles || [],
      role: ex.role
    };
  });
} catch (e) {
  console.log('Warning: Could not build exercise lookup:', e.message);
}

// === CONFIGURACIÓN ===
const WARMUP_BUFFER = 600; // 10 min calentamiento
const TRANSITION_TIME = 120; // 2 min entre ejercicios (cambio de máquina/setup)
const MIN_EXERCISES = 4; // Nunca dejar menos de 4 ejercicios por día

// === HELPERS ===

function parseSessionDuration(durationStr) {
  if (!durationStr) return 70;
  if (durationStr.includes('45')) return 55;
  if (durationStr.includes('60') || durationStr.includes('75')) return 70;
  if (durationStr.includes('90') || durationStr.includes('Mas de 75')) return 85;
  return 70;
}

function parseTempo(tempoStr) {
  if (!tempoStr || typeof tempoStr !== 'string') return 4;
  return tempoStr.split('-')
    .map(n => parseInt(n, 10) || 0)
    .reduce((sum, phase) => sum + phase, 0);
}

function calculateExerciseTime(exercise) {
  const sets = parseInt(exercise.sets, 10) || 3;
  const reps = parseInt(exercise.reps, 10) || 10;
  const restSeconds = parseInt(exercise['rest-seconds'] || exercise.rest_seconds, 10) || 60;
  const tempoPerRep = parseTempo(exercise.tempo);

  const workTime = sets * reps * tempoPerRep;
  const restTime = (sets - 1) * restSeconds;

  return workTime + restTime;
}

function calculateDayDuration(exercises) {
  if (!exercises || exercises.length === 0) return 0;

  const exerciseTime = exercises.reduce((sum, ex) =>
    sum + calculateExerciseTime(ex), 0
  );
  const transitions = (exercises.length - 1) * TRANSITION_TIME;
  return (exerciseTime + transitions + WARMUP_BUFFER) / 60;
}

// Nueva función: Calcular prioridad de un ejercicio
// Mayor score = más protegido (reducir/eliminar ÚLTIMO)
function getPriorityScore(exercise, priorityMuscles, exerciseLookup) {
  const exInfo = exerciseLookup[exercise.exercise_id] || {};
  const mainMuscle = exInfo.main_muscle || '';
  const secondaryMuscles = exInfo.secondary_muscles || [];

  const mainMatch = priorityMuscles.includes(mainMuscle);
  const secondaryMatch = secondaryMuscles.some(m => priorityMuscles.includes(m));
  const isPriority = mainMatch || secondaryMatch;

  // Base score por rol: isolation=0, core=20, compound=40
  const roleBase = { isolation: 0, core: 20, compound: 40 };
  // Bonus si es músculo prioritario: +10
  const priorityBonus = isPriority ? 10 : 0;

  return (roleBase[exercise.role] || 20) + priorityBonus;
}

function reduceWorkout(exercises, targetMin, priorityMuscles, weekNumber, exerciseLookup) {
  let currentDuration = calculateDayDuration(exercises);
  let iterations = 0;
  const MAX_ITER = 30;

  // Mínimo de series: 3 para semanas 1-3 (hipertrofia), 2 para semana 4 (descarga)
  const MIN_SETS = weekNumber === 4 ? 2 : 3;

  const reductionLog = [];

  // === FASE 1: Reducir series hasta mínimo ===
  while (currentDuration > targetMin && iterations < MAX_ITER) {
    const reducible = exercises
      .map((ex, idx) => ({
        idx,
        sets: parseInt(ex.sets, 10),
        min: MIN_SETS,
        role: ex.role,
        exercise_id: ex.exercise_id,
        priorityScore: getPriorityScore(ex, priorityMuscles, exerciseLookup),
        impact: calculateExerciseTime({...ex, sets: "1"})
      }))
      .filter(r => r.sets > r.min)
      .sort((a, b) => {
        // Menor score = reducir primero (menos protegido)
        if (a.priorityScore !== b.priorityScore) {
          return a.priorityScore - b.priorityScore;
        }
        // Mismo score: mayor impacto primero (más ahorro de tiempo)
        return b.impact - a.impact;
      });

    if (reducible.length === 0) break;

    const target = reducible[0];
    const oldSets = target.sets;
    exercises[target.idx].sets = String(target.sets - 1);
    currentDuration = calculateDayDuration(exercises);
    iterations++;

    reductionLog.push({
      phase: 1,
      action: 'reduce_sets',
      exercise_id: target.exercise_id,
      from_sets: oldSets,
      to_sets: oldSets - 1,
      priority_score: target.priorityScore
    });
  }

  // === FASE 2: Eliminar ejercicios si aún excede ===
  let removedExercises = [];

  while (currentDuration > targetMin && exercises.length > MIN_EXERCISES) {
    // Encontrar ejercicio de menor prioridad para eliminar
    const removable = exercises
      .map((ex, idx) => {
        const priorityScore = getPriorityScore(ex, priorityMuscles, exerciseLookup);
        const exInfo = exerciseLookup[ex.exercise_id] || {};
        const isCompoundPriority = ex.role === 'compound' && 
          priorityMuscles.includes(exInfo.main_muscle);

        return {
          idx,
          exercise_id: ex.exercise_id,
          priorityScore,
          isCompoundPriority,
          timeImpact: calculateExerciseTime(ex) + TRANSITION_TIME
        };
      })
      // NUNCA eliminar compound prioritarios
      .filter(r => !r.isCompoundPriority)
      .sort((a, b) => {
        // Menor score = eliminar primero
        if (a.priorityScore !== b.priorityScore) {
          return a.priorityScore - b.priorityScore;
        }
        // Mismo score: mayor impacto de tiempo primero
        return b.timeImpact - a.timeImpact;
      });

    if (removable.length === 0) break;

    // Eliminar el de menor prioridad
    const toRemove = removable[0];
    const removedEx = exercises.splice(toRemove.idx, 1)[0];
    removedExercises.push(removedEx.exercise_id);
    currentDuration = calculateDayDuration(exercises);

    reductionLog.push({
      phase: 2,
      action: 'remove_exercise',
      exercise_id: toRemove.exercise_id,
      priority_score: toRemove.priorityScore,
      time_saved_sec: toRemove.timeImpact
    });
  }

  return {
    exercises,
    duration: currentDuration,
    adjusted: iterations > 0 || removedExercises.length > 0,
    meetsTarget: currentDuration <= targetMin,
    reductionLog,
    removedExercises,
    setsReduced: iterations,
    minSetsUsed: MIN_SETS
  };
}

// === PROCESAMIENTO ===

const targetMinutes = parseSessionDuration(userProfile.session_duration_mins);

// Agrupar workouts por semana y día
const grouped = {};
allWorkouts.forEach(w => {
  const key = `W${w.week_number}-${w.day_name}`;
  if (!grouped[key]) grouped[key] = [];
  grouped[key].push(w);
});

// Validar cada día
const processedWorkouts = [];
const validationLog = [];

for (const [key, dayWorkouts] of Object.entries(grouped)) {
  const [week, dayName] = key.split('-');
  const weekNumber = parseInt(week.replace('W', ''), 10);
  const initialDuration = calculateDayDuration(dayWorkouts);
  const initialExerciseCount = dayWorkouts.length;

  if (initialDuration > targetMinutes) {
    const result = reduceWorkout(dayWorkouts, targetMinutes, priorityMuscles, weekNumber, exerciseLookup);

    validationLog.push({
      week,
      day: dayName,
      initial_min: Math.round(initialDuration),
      final_min: Math.round(result.duration),
      target_min: targetMinutes,
      initial_exercises: initialExerciseCount,
      final_exercises: result.exercises.length,
      sets_reduced: result.setsReduced,
      exercises_removed: result.removedExercises,
      min_sets_used: result.minSetsUsed,
      adjusted: result.adjusted,
      status: result.meetsTarget ? 'OK' : 'OVER_TARGET'
    });

    processedWorkouts.push(...result.exercises);
  } else {
    validationLog.push({
      week,
      day: dayName,
      duration_min: Math.round(initialDuration),
      target_min: targetMinutes,
      exercises: dayWorkouts.length,
      status: 'OK_NO_CHANGE'
    });

    processedWorkouts.push(...dayWorkouts);
  }
}

// Log de validación
console.log('=== WORKOUT TIME VALIDATION v2.0 ===');
console.log('User:', userProfile.whatsapp_id);
console.log('Target Session:', targetMinutes, 'min');
console.log('Priority Muscles:', priorityMuscles.join(', ') || 'None');
console.log('Input items:', allWorkouts.length);
console.log('Results:', JSON.stringify(validationLog, null, 2));
console.log('Total workouts procesados:', processedWorkouts.length);

// Retornar workouts procesados - cada uno como item separado
return processedWorkouts.map(w => ({ json: w }));
